```apex
/**
 * Base class for every payment-terms related error.
 *
 * Catching this single type lets callers handle all terms failures
 * (unsupported format, out-of-range value, ...) in one place:
 *
 *     try {
 *         Date due = PaymentTerms.dueDate(invoice.InvoiceDate, invoice.Payment_Terms__c);
 *     } catch (PaymentTermsException e) {
 *         // handle any terms problem
 *     }
 *
 * The class is declared 'virtual' so that it can be extended by
 * UnsupportedTermsException and TermsOutOfRangeException (exception classes
 * extending Exception are otherwise implicitly final).
 */
public virtual class PaymentTermsException extends Exception {
}
