/**
 * Unit tests for AddressVerificationService.
 *
 * The tests are self contained (no SeeAllData and no DML, so no uncommitted work can
 * interfere with the mocked callouts) and use an inner HttpCalloutMock implementation
 * so that the full request contract (endpoint, method, headers, body) and every
 * documented outcome (SKIPPED / VERIFIED / CORRECTED / INVALID / HTTP error) are asserted.
 */
@IsTest
private class AddressVerificationServiceTest {

    private static final String ENDPOINT = 'callout:FB_Address_API/v2/verify';
    private static final String CONTENT_TYPE = 'application/json';

    private static final String STREET = '221B Baker Street';
    private static final String CITY = 'London';
    private static final String POSTAL_CODE = 'NW1 6XE';
    private static final String COUNTRY = 'United States';

    private static final String CORRECTED_STREET = '1 Corrected Street';
    private static final String CORRECTED_CITY = 'Correctville';
    private static final String CORRECTED_POSTAL_CODE = '54321';
    private static final String CORRECTED_COUNTRY = 'United States';

    /**
     * Configurable HttpCalloutMock: records the request that was sent and returns
     * the configured status code / body.
     */
    private class AddressApiMock implements HttpCalloutMock {
        Integer statusCode = 200;
        String responseBody = '{"status":"VERIFIED"}';

        HttpRequest lastRequest;
        Integer callCount = 0;

        public HttpResponse respond(HttpRequest request) {
            this.lastRequest = request;
            this.callCount += 1;

            HttpResponse res = new HttpResponse();
            res.setStatusCode(this.statusCode);
            res.setStatus(this.statusCode == 200 ? 'OK' : 'ERROR');
            res.setHeader('Content-Type', CONTENT_TYPE);
            res.setBody(this.responseBody);
            return res;
        }
    }

    /**
     * Builds an in-memory (not persisted) account so that no DML is required.
     */
    private static Account newAccount(String street, String city, String postalCode, String country) {
        return new Account(
            Name = 'Address Verification Test Account',
