            'The handler must use at most one SOQL query per trigger execution');
        System.assert(statementsAfter - statementsBefore <= 3,
            'The handler must use a constant, small number of DML statements per trigger execution');
        System.assert(rowsAfter - rowsBefore <= 403,
            'The handler must not write more rows than the opportunities, the tasks and the accounts that need it');

        List<Opportunity> savedOpps = [SELECT Id, StageName, NextStep FROM Opportunity];
        System.assertEquals(BULK_SIZE, savedOpps.size(), 'All opportunities must be created');
        Set<Id> oppIds = new Set<Id>();
