        System.assertEquals(renewal.Amount.scale(), 2, 'The renewal amount should have a scale of 2');
        System.assert(renewalRegistration.relationshipField == null, 'The renewal should not be registered with a relationship');
        System.assert(renewalRegistration.relatedRecord == null, 'The renewal should not be registered with a related record');

        // ---- the reminder task ----
