        System.assertEquals(taskRegistration.relationshipField, Task.WhatId, 'The task should be registered against Task.WhatId');
        System.assert(taskRegistration.relatedRecord === renewal, 'The task should be related to the renewal opportunity');
        System.assert(taskRegistration.relatedRecord !== original, 'The task should not be related to the original opportunity');

        // Work is committed once
        System.assertEquals(uowMock.commitCount, 1, 'Work should be committed exactly once');
        System.assertEquals(uowMock.rollbackCount, 0, 'Work should never be rolled back');
    }

