/**
 * @description Pure unit tests for OpportunitiesService.applyDiscounts.
 *
 * No DML and no SOQL is executed by this test class:
 *  - the opportunities selector is replaced by a mock that returns in-memory records;
 *  - the Opportunities domain is replaced by a mock (the real domain is not exercised,
 *    it has its own test class);
 *  - the unit of work is replaced by a mock, so nothing is ever committed.
 *
 * The mocks are injected through the fflib application factories
 * (Application.Selector.setMock, Application.Domain.setMock and
 * Application.UnitOfWork.setMock) while fflib_ApexMocks is active.
 * Opportunity ids are fakes produced by fflib_IDGenerator, so no records have to be
 * created in the org.
 */
@IsTest
public class OpportunitiesServiceTest {
    private static final Decimal VALID_DISCOUNT = 25;
    private static final Decimal MAX_DISCOUNT = 50;
    private static final String EXPECTED_ERROR_MESSAGE =
        'Discount must be greater than 0 and at most 50 percent.';

