    /**
     * @description Asserts that an invalid discount percentage is rejected with an
     *              OpportunitiesServiceException and that neither the domain nor the
     *              unit of work (nor the selector) is used.
     */
    private static void assertDiscountIsRejected(Decimal discountPercentage) {
        List<Opportunity> opportunities = buildOpportunities(2);
        Set<Id> opportunityIds = idsOf(opportunities);
        mockCollaborators(opportunities);

        Boolean exceptionThrown = false;

        Test.startTest();
        try {
            OpportunitiesService.applyDiscounts(opportunityIds, discountPercentage);
        } catch (OpportunitiesService.OpportunitiesServiceException e) {
            exceptionThrown = true;
            Assert.areEqual(EXPECTED_ERROR_MESSAGE, e.getMessage(), 'Unexpected exception message');
        }
        Test.stopTest();

        Assert.isTrue(
            exceptionThrown,
            'An OpportunitiesServiceException was expected for a discount percentage of ' + discountPercentage
        );
        Assert.areEqual(0, selectorMock.selectByIdCallCount, 'The selector must not be queried for an invalid discount');
        Assert.areEqual(0, domainMock.applyDiscountCallCount, 'The domain must not be used for an invalid discount');
        Assert.areEqual(0, unitOfWorkMock.commitWorkCallCount, 'The unit of work must not commit for an invalid discount');
    }

    /**
     * @description Asserts that no discount was applied and nothing was committed.
     */
    private static void assertNothingWasApplied() {
        Assert.areEqual(0, selectorMock.selectByIdCallCount, 'The selector must not be queried');
        Assert.areEqual(0, domainMock.applyDiscountCallCount, 'The domain must not be used');
        Assert.areEqual(0, unitOfWorkMock.commitWorkCallCount, 'The unit of work must not commit');
        Assert.isFalse(MockOpportunities.discountApplied, 'No discount must have been applied');
    }

    /**
     * @description Registers the selector, domain and unit of work mocks in the
     *              fflib application factories.
