    private static void mockCollaborators(List<Opportunity> opportunities) {
        selectorMock = new MockOpportunitiesSelector(opportunities);
        domainMock = new MockOpportunities(asSObjects(opportunities));
        unitOfWorkMock = new MockUnitOfWork();

        Application.Selector.setMock(Opportunity.SObjectType, selectorMock);
        Application.Domain.setMock(Opportunity.SObjectType, domainMock);
        Application.UnitOfWork.setMock(unitOfWorkMock);
    }

    /**
     * @description Builds in-memory opportunities with fake ids, no DML involved.
     */
    private static List<Opportunity> buildOpportunities(Integer recordCount) {
        List<Opportunity> opportunities = new List<Opportunity>();
        for (Integer i = 0; i < recordCount; i++) {
            opportunities.add(
                new Opportunity(
                    Id = fflib_IDGenerator.generateId(Opportunity.SObjectType),
                    Name = 'Opportunity ' + i,
                    Amount = 100 + i
                )
            );
        }
        return opportunities;
    }

    private static List<SObject> asSObjects(List<Opportunity> opportunities) {
        List<SObject> records = new List<SObject>();
        for (Opportunity opportunity : opportunities) {
            records.add(opportunity);
        }
        return records;
    }

    private static Set<Id> idsOf(List<Opportunity> opportunities) {
        Set<Id> ids = new Set<Id>();
        for (Opportunity opportunity : opportunities) {
            ids.add(opportunity.Id);
        }
        return ids;
    }
