/**
 * Unit tests for OpportunityForecastService.weightedAmountByStage.
 *
 * These are pure unit tests: no DML is executed and no SOQL is run. The
 * IOpportunitiesSelector is replaced with an ApexMocks mock which is registered
 * through Application.Selector.setMock, and the opportunities handed back to the
 * service are built in memory with fake ids produced by fflib_IDGenerator.
 */
@IsTest
public class OpportunityForecastServiceTest {
    private static final String STAGE_PROSPECTING = 'Prospecting';
    private static final String STAGE_QUALIFICATION = 'Qualification';
    private static final String STAGE_PROPOSAL = 'Proposal';

    /**
     * The weighted amount (Amount * Probability / 100, rounded to 2 decimals per
     * opportunity) is summed per StageName over the opportunities returned by
     * selectOpenByAccountIds.
     */
    @IsTest
    static void weightedAmountByStage_sumsWeightedAmountsPerStage() {
        Id accountOne = fakeId(Account.SObjectType);
        Id accountTwo = fakeId(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>{ accountOne, accountTwo };

        List<Opportunity> opportunities = new List<Opportunity>{
            buildOpportunity(accountOne, STAGE_PROSPECTING, 1000.00, 50),
            buildOpportunity(accountOne, STAGE_PROSPECTING, 200.55, 33),
            buildOpportunity(accountTwo, STAGE_QUALIFICATION, 5000.00, 25),
            buildOpportunity(accountTwo, STAGE_PROPOSAL, 1200.00, 75)
        };

        stubSelector(accountIds, opportunities);

        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);

        Assert.isNotNull(result, 'A result map is always expected');
        Assert.areEqual(
            new Set<String>{ STAGE_PROSPECTING, STAGE_QUALIFICATION, STAGE_PROPOSAL },
            result.keySet(),
            'One entry is expected per stage that has opportunities'
        );
        // 1000.00 * 50% = 500.00 and 200.55 * 33% = 66.1815 rounded to 66.18
        Assert.areEqual(566.18, result.get(STAGE_PROSPECTING), 'Weighted amounts of the same stage are summed');
        Assert.areEqual(1250.00, result.get(STAGE_QUALIFICATION), '5000.00 * 25%');
        Assert.areEqual(900.00, result.get(STAGE_PROPOSAL), '1200.00 * 75%');
    }

    /**
     * Opportunities without an Amount or without a Probability are ignored, so they
     * do not even create an entry for their stage.
     */
    @IsTest
    static void weightedAmountByStage_ignoresOpportunitiesMissingAmountOrProbability() {
        Id accountId = fakeId(Account.SObjectType);
        Set<Id> accountIds = new Set<Id>{ accountId };

        List<Opportunity> opportunities = new List<Opportunity>{
            buildOpportunity(accountId, STAGE_PROSPECTING, null, 50),
            buildOpportunity(accountId, STAGE_QUALIFICATION, 1000.00, null),
            buildOpportunity(accountId, STAGE_PROPOSAL, 1000.00, 40)
        };

        stubSelector(accountIds, opportunities);

        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);

        Assert.isNotNull(result, 'A result map is always expected');
        Assert.areEqual(1, result.size(), 'Only the stage of the complete opportunity is expected');
        Assert.isFalse(result.containsKey(STAGE_PROSPECTING), 'Opportunity without amount must be ignored');
        Assert.isFalse(
            result.containsKey(STAGE_QUALIFICATION),
            'Opportunity without probability must be ignored'
        );
        Assert.areEqual(400.00, result.get(STAGE_PROPOSAL), '1000.00 * 40%');
    }

    /**
     * A null set of account ids returns an empty map without calling the selector.
     */
    @IsTest
    static void weightedAmountByStage_returnsEmptyMapForNullAccountIds() {
        Set<Id> accountIds = null;

        // Trap: should the selector ever be called, opportunities would come back
        // and the result would not be empty.
        stubSelector(accountIds, new List<Opportunity>{
            buildOpportunity(fakeId(Account.SObjectType), STAGE_PROSPECTING, 1000.00, 50)
        });

        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);

        Assert.isNotNull(result, 'A result map is always expected');
        Assert.areEqual(0, result.size(), 'No weighted amount is expected for null account ids');
        Assert.isTrue(result.isEmpty(), 'The result must be empty for null account ids');
    }

    /**
     * An empty set of account ids returns an empty map without calling the selector.
     */
    @IsTest
    static void weightedAmountByStage_returnsEmptyMapForEmptyAccountIds() {
        Set<Id> accountIds = new Set<Id>();

        // Trap: should the selector ever be called, opportunities would come back
        // and the result would not be empty.
        stubSelector(accountIds, new List<Opportunity>{
            buildOpportunity(fakeId(Account.SObjectType), STAGE_PROSPECTING, 1000.00, 50)
        });

        Map<String, Decimal> result = OpportunityForecastService.weightedAmountByStage(accountIds);

        Assert.isNotNull(result, 'A result map is always expected');
        Assert.areEqual(0, result.size(), 'No weighted amount is expected for empty account ids');
        Assert.isTrue(result.isEmpty(), 'The result must be empty for empty account ids');
    }

    /**
     * Creates the ApexMocks mock for IOpportunitiesSelector, registers it through
     * Application.Selector.setMock and stubs selectOpenByAccountIds.
     */
    private static void stubSelector(Set<Id> accountIds, List<Opportunity> opportunities) {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        mocks.startStubbing();
        IOpportunitiesSelector selectorMock = (IOpportunitiesSelector) mocks.mock(IOpportunitiesSelector.class);
        Application.Selector.setMock(Opportunity.SObjectType, selectorMock);
        mocks.when(selectorMock.selectOpenByAccountIds(accountIds)).thenReturn(opportunities);
        mocks.stopStubbing();
    }

    /**
     * Builds an in-memory (never persisted) opportunity with a fake id.
     */
    private static Opportunity buildOpportunity(
        Id accountId,
        String stageName,
        Decimal amount,
        Decimal probability
    ) {
        return new Opportunity(
            Id = fakeId(Opportunity.SObjectType),
            Name = 'Test Opportunity ' + stageName,
            AccountId = accountId,
            StageName = stageName,
            Amount = amount,
            Probability = probability
        );
    }

    /**
     * Returns a fake (never persisted) Id for the given SObject type, generated with
     * fflib_IDGenerator.
     *
     * The generator is invoked reflectively so that the test keeps working with any
     * of the overloads fflib_IDGenerator offers (SObject type, type name or no
     * argument) and whether the generator is used statically or through an instance.
     * If none of the overloads can be applied, a deterministic fake id is used so
     * that the unit test never depends on the database.
     */
    private static Id fakeId(Schema.SObjectType sobjectType) {
        List<List<Object>> argumentCandidates = new List<List<Object>>{
            new List<Object>{ sobjectType },
            new List<Object>{ sobjectType.getDescribe().getName() },
            new List<Object>()
        };

        List<Method> methods = fflib_IDGenerator.class.getMethods();
        for (Method method : methods) {
            if (method.getName() != 'generateId') {
                continue;
            }
            for (List<Object> arguments : argumentCandidates) {
                Id generated = invokeGenerator(method, null, arguments);
                if (generated != null) {
                    return generated;
                }
                try {
                    generated = invokeGenerator(
                        method,
                        fflib_IDGenerator.class.newInstance(),
                        arguments
                    );
                } catch (Exception e) {
                    // The generator cannot be instantiated, fall back to the next candidate.
                }
                if (generated != null) {
                    return generated;
                }
            }
        }
        return fallbackId(sobjectType);
    }

    /**
     * Invokes a single fflib_IDGenerator method and converts its result into an Id.
     * Returns null when the method cannot be applied with the given arguments.
     */
    private static Id invokeGenerator(Method method, Object instance, List<Object> arguments) {
        try {
            Object generated = method.invoke(instance, arguments);
            if (generated == null) {
                return null;
            }
            String value = String.valueOf(generated);
            if (value == null) {
                return null;
            }
            value = value.trim();
            if (value.length() == 15 || value.length() == 18) {
                return (Id) value;
            }
        } catch (Exception e) {
            // Signature mismatch or inaccessible member: try the next candidate.
        }
        return null;
    }

    /**
     * Deterministic fake id, used only when fflib_IDGenerator cannot produce one.
     */
    private static Id fallbackId(Schema.SObjectType sobjectType) {
        String keyPrefix = sobjectType.getDescribe().getKeyPrefix();
        return (Id) (keyPrefix + '000000000000000');
    }
}
