/**
 * Domain class for Opportunity.
 *
 * Starts fulfilment whenever an Opportunity is won:
 *  - inserted with StageName = 'Closed Won'
 *  - updated so that StageName becomes 'Closed Won' from any other stage
 *
 * Editing an Opportunity that is already 'Closed Won' does not start fulfilment again.
 *
 * The fulfilment service is resolved through the Application Service Factory so that
 * it can be replaced with a mock in tests.
 */
public class Opportunities extends fflib_SObjectDomain {

    private static final String CLOSED_WON = 'Closed Won';

    /**
     * Standard fflib constructor factory, used by fflib_SObjectDomain.triggerHandler()
     * to build the domain instance for the records of the current trigger invocation.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities(records);
        }
    }

    private final List<Opportunity> opportunities;

    public Opportunities(List<SObject> records) {
        super(records);
        this.opportunities = new List<Opportunity>();
        for (SObject record : records) {
            if (record != null) {
                this.opportunities.add((Opportunity) record);
            }
        }
    }

    public void beforeInsert() {
    }

    public void beforeUpdate() {
    }

    public void beforeDelete() {
    }

    public void afterInsert() {
        startFulfilmentForWonOpportunities();
    }

    public void afterUpdate() {
        startFulfilmentForWonOpportunities();
    }

    public void afterDelete() {
    }

    public void afterUndelete() {
    }

    /**
     * Collects every Opportunity of this invocation that qualifies for fulfilment and
     * calls the fulfilment service at most once, with all of the qualifying ids.
     */
    private void startFulfilmentForWonOpportunities() {
        // Fulfilment may only start once the records are persisted (ids available).
        if (!Trigger.isAfter) {
            return;
        }

        Set<Id> qualifyingIds = new Set<Id>();

        for (Opportunity opportunity : opportunities) {
            if (opportunity == null || opportunity.StageName != CLOSED_WON) {
                continue;
            }

            if (Trigger.isUpdate) {
                // Already 'Closed Won' before this update: does not qualify again.
                Opportunity oldOpportunity = (Opportunity) Trigger.oldMap.get(opportunity.Id);
                if (oldOpportunity != null && oldOpportunity.StageName == CLOSED_WON) {
                    continue;
                }
            }

            if (opportunity.Id != null) {
                qualifyingIds.add(opportunity.Id);
            }
        }

        if (qualifyingIds.isEmpty()) {
            return;
        }

        IOpportunityFulfilmentService fulfilmentService =
            (IOpportunityFulfilmentService) Application.Service.newInstance(IOpportunityFulfilmentService.class);

        fulfilmentService.startFulfilment(qualifyingIds);
    }
}
