/**
 * Selector for the Contact SObject.
 *
 * All Contact queries in the org should be executed through this selector so that
 * the queried field set stays consistent and centrally managed.
 *
 * The defaults of the fflib base class are left untouched:
 *  - no extra ORDER BY is applied (base class default ordering is kept)
 *  - no extra security enforcement / CRUD or FLS overrides are applied
 */
public class ContactsSelector extends fflib_SObjectSelector {

    /**
     * The fields queried by this selector.
     * "Id" is always included so that the returned records can be correlated
     * with the ids that were requested.
     */
    public static final List<String> FIELD_LIST = new List<String>{
        'Id',
        'FirstName',
        'LastName',
        'Email',
        'Title',
        'AccountId'
    };

    /**
     * The same field set expressed as Schema fields.
     */
    public static final List<Schema.SObjectField> SCHEMA_FIELD_LIST = new List<Schema.SObjectField>{
        Contact.Id,
        Contact.FirstName,
        Contact.LastName,
        Contact.Email,
        Contact.Title,
        Contact.AccountId
    };

    /**
     * Default constructor: binds the selector to the Contact SObject and to
     * the field list above.
     */
    public ContactsSelector() {
        super(FIELD_LIST, Contact.SObjectType);
    }

    /**
     * The SObject type handled by this selector.
     */
    public Schema.SObjectType getSObjectType() {
        return Contact.SObjectType;
    }

    /**
     * The fields queried by this selector.
     */
    public List<Schema.SObjectField> getSObjectFieldList() {
        return SCHEMA_FIELD_LIST;
    }

    /**
     * Returns the Contacts whose Ids are contained in the supplied set.
     * Every field of the selector's field list is populated on the returned
     * records and the records are retrieved with a single query.
     *
     * @param contactIds the Ids of the Contacts to retrieve
     * @return the matching Contacts, or an empty List when no Ids are supplied
     */
    public List<Contact> selectById(Set<Id> contactIds) {
        // Guard against empty (or null) input: no query is executed at all.
        if (contactIds == null || contactIds.isEmpty()) {
            return new List<Contact>();
        }

        // Build the SELECT list from the selector's own field list so that the
        // queried fields can never drift from the field list definition.
        List<String> fieldNames = new List<String>();
        for (Schema.SObjectField field : getSObjectFieldList()) {
            fieldNames.add(field.getName());
        }

        // The id set is bound (never concatenated), which keeps the query safe
        // from SOQL injection and heap-safe for large id sets.
        String query =
            'SELECT ' + String.join(fieldNames, ', ') +
            ' FROM Contact' +
            ' WHERE Id IN :contactIds';

        return (List<Contact>) Database.query(query);
    }
}
