import { LightningElement, api, track } from 'lwc';

import ADD_LABEL from '@salesforce/label/c.Favorite_Add';
import REMOVE_LABEL from '@salesforce/label/c.Favorite_Remove';

/**
 * Icon-style toggle button that marks a record as a favourite.
 *
 * The parent owns the `favorite` public property. Every value pushed by the
 * parent is authoritative: the button always renders the value it receives.
 * A click flips the rendered value immediately (optimistic UI) and notifies
 * the parent through the `favoritechange` event.
 *
 * @fires favoritechange {detail: {favorite: boolean}}
 */
export default class FavoriteToggle extends LightningElement {
    /**
     * Value currently rendered by the button.
     * @type {boolean}
     */
    @track isFavorite = false;

    /**
     * Public property set by the parent.
     *
     * Reading it returns the state currently shown by the button, writing it
     * (which is what the parent does) updates the button to that value.
     *
     * @type {boolean}
     */
    @api
    get favorite() {
        return this.isFavorite;
    }

    set favorite(value) {
        // The parent is the source of truth: whenever it pushes a value the
        // button has to show exactly that value.
        this.isFavorite = Boolean(value);
    }

    /**
     * ARIA pressed state of the toggle button.
     * @returns {string} 'true' when the record is a favourite, 'false' otherwise.
     */
    get pressedAttribute() {
        return this.isFavorite ? 'true' : 'false';
    }

    /**
     * Label of the action that a click performs.
     * @returns {string} Custom label of the add or remove action.
     */
    get actionLabel() {
        return this.isFavorite ? REMOVE_LABEL : ADD_LABEL;
    }

    /**
     * Fill of the star icon: solid when the record is a favourite.
     * @returns {string} SVG fill value.
     */
    get iconFill() {
        return this.isFavorite ? 'currentColor' : 'none';
    }

    /**
     * Flips the state optimistically and notifies the parent.
     * @returns {void}
     */
    handleClick() {
        const newValue = !this.isFavorite;

        // Optimistic update: show the new state right away.
        this.isFavorite = newValue;

        this.dispatchEvent(
            new CustomEvent('favoritechange', {
                detail: { favorite: newValue },
                bubbles: true,
                composed: true
            })
        );
    }
}
