import { LightningElement, wire } from 'lwc';
import {
    MessageContext,
    subscribe,
    unsubscribe,
    publish,
    APPLICATION_SCOPE
} from 'lightning/messageService';

/**
 * The Lightning message channel used to broadcast the selected account.
 * The channel is referenced through its descriptor object so that subscribe()
 * and publish() always address exactly the same channel.
 */
const ACCOUNT_SELECTED_CHANNEL = { channel: 'Account_Selected__c' };

export default class AccountDetailsPanel extends LightningElement {
    /** Id of the account that is currently selected. `null` = nothing selected. */
    accountId = null;

    /** Message context handed over by the platform through @wire(MessageContext). */
    messageContext;

    /** The one and only subscription held by this component instance. */
    subscription;

    /** Guard that makes sure this component never holds more than one subscription. */
    isSubscribed = false;

    /**
     * The message context is delivered asynchronously by the platform. As soon as
     * it is available we (re)establish the subscription.
     */
    @wire(MessageContext)
    wiredMessageContext(messageContext) {
        this.messageContext = messageContext;
        this.ensureSubscription();
    }

    connectedCallback() {
        // Subscribe as soon as the component is inserted. If the message context
        // has not been delivered yet the attempt fails and is retried by
        // wiredMessageContext() as soon as the context is available.
        this.ensureSubscription();
    }

    disconnectedCallback() {
        // Release the subscription when the component leaves the page, so that a
        // later re-insertion (e.g. a reopened tab) subscribes again - and only
        // one subscription is ever held.
        this.releaseSubscription();
    }

    ensureSubscription() {
        if (this.isSubscribed) {
            return;
        }

        let subscription;
        try {
            subscription = subscribe(
                this.messageContext,
                ACCOUNT_SELECTED_CHANNEL,
                this.handleAccountSelected,
                { scope: APPLICATION_SCOPE }
            );
        } catch (error) {
            // No usable message context yet: retry from wiredMessageContext().
            return;
        }

        this.subscription = subscription;
        this.isSubscribed = true;
    }

    releaseSubscription() {
        this.isSubscribed = false;
        const subscription = this.subscription;
        this.subscription = undefined;
        try {
            unsubscribe(subscription);
        } catch (error) {
            // There was nothing to unsubscribe from.
        }
    }

    /** Handles every message published on Account_Selected__c. */
    handleAccountSelected = (message) => {
        this.accountId = message && message.recordId ? message.recordId : null;
    };

    /** Clears the selection locally and for every other listening component. */
    handleClearSelection = () => {
        // Clear locally right away - this panel also receives its own message.
        this.accountId = null;
        try {
            publish(
                this.messageContext,
                ACCOUNT_SELECTED_CHANNEL,
                { recordId: null },
                { scope: APPLICATION_SCOPE }
            );
        } catch (error) {
            // Publishing without a message context is not possible.
        }
    };
}
