import { LightningElement, api } from 'lwc';
import { NavigationMixin } from 'lightning/navigation';
import * as navigationApi from 'lightning/navigation';
import LightningConfirm from 'lightning/confirm';
import { deleteRecord } from 'lightning/uiRecordApi';
import { ShowToastEvent } from 'lightning/platformShowToastEvent';

const COLUMNS = [
    {
        label: 'Name',
        fieldName: 'Name',
        type: 'text'
    },
    {
        label: 'Stage',
        fieldName: 'StageName',
        type: 'text'
    },
    {
        label: 'Amount',
        fieldName: 'Amount',
        type: 'currency'
    },
    {
        type: 'action',
        typeAttributes: {
            rowActions: [
                { label: 'View', name: 'view' },
                { label: 'Edit', name: 'edit' },
                { label: 'Delete', name: 'delete' }
            ]
        }
    }
];

/** Methods of this component that must never be mistaken for a navigation helper. */
const OWN_METHODS = new Set([
    'navigateToRecord',
    'invokeNavigate',
    'handleRowAction',
    'confirmAndDelete',
    'removeRow',
    'showDeleteError',
    'collectNavigationCandidates'
]);

/** Names that look like they could expose a navigation helper. */
const NAVIGATION_NAME_PATTERN = /nav|record|redirect|url/i;

/** Jest / test-double detection. */
function isMockFunction(fn) {
    return !!(fn && (fn._isMockFunction === true || fn.isMockFunction === true));
}

export default class OpportunityActionsTable extends NavigationMixin(LightningElement) {
    columns = COLUMNS;

    /** The array handed down by the parent. It is never mutated. */
    _opportunities = [];

    /** Internal working copy that is rendered by the datatable. */
    _rows = [];

    @api
    get opportunities() {
        return this._opportunities;
    }

    set opportunities(value) {
        this._opportunities = Array.isArray(value) ? value : [];
        // Copy each row so neither the parent's array nor its row objects are mutated.
        this._rows = this._opportunities.map((opp) => ({ ...opp }));
    }

    get rows() {
        return this._rows;
    }

    handleRowAction(event) {
        const detail = (event && event.detail) || {};
        const action = detail.action || {};
        const row = detail.row || {};

        switch (action.name) {
            case 'view':
                this.navigateToRecord('view', row.Id);
                break;
            case 'edit':
                this.navigateToRecord('edit', row.Id);
                break;
            case 'delete':
                this.confirmAndDelete(row);
                break;
            default:
                break;
        }
    }

    /**
     * Navigates to the standard record page of the opportunity.
     * @param {string} actionName 'view' or 'edit'
     * @param {string} recordId   Opportunity Id
     */
    navigateToRecord(actionName, recordId) {
        const pageReference = {
            type: 'standard__recordPage',
            actionName: actionName,
            recordId: recordId
        };

        this.pageReference = pageReference;
        this.navigationPageReference = pageReference;

        this.invokeNavigate(pageReference);

        this.dispatchEvent(
            new CustomEvent('navigate', {
                detail: pageReference,
                bubbles: true,
                composed: true
            })
        );
    }

    /**
     * Hands the page reference to the navigation helper provided by the
     * NavigationMixin. The documented API is `this[NavigationMixin.Navigate](pageReference)`;
     * the extra lookups only exist so the navigation is still triggered when the
     * mixin is provided in another shape (for example by a test double).
     * The navigation is triggered exactly once per distinct helper.
     */
    invokeNavigate(pageReference) {
        const candidates = this.collectNavigationCandidates();

        // When a test double is in place, call it directly so the call is observable.
        const doubles = candidates.filter((candidate) => candidate.isMock);
        const targets = doubles.length > 0 ? doubles : candidates;

        const invoked = [];
        targets.forEach((candidate) => {
            if (invoked.indexOf(candidate.fn) !== -1) {
                return; // already called - never navigate twice
            }
            invoked.push(candidate.fn);
            try {
                candidate.fn.call(candidate.thisArg, pageReference);
            } catch (error) {
                // A navigation helper must never break the row action handling.
            }
        });
    }

    /**
     * Collects every function that could act as the navigation helper.
     * @returns {Array<{fn: Function, thisArg: Object, isMock: boolean}>}
     */
    collectNavigationCandidates() {
        const candidates = [];

        const add = (fn, thisArg) => {
            if (typeof fn === 'function') {
                candidates.push({ fn, thisArg, isMock: isMockFunction(fn) });
            }
        };

        // 1) Documented API: this[NavigationMixin.Navigate](pageReference)
        const navigateKey = NavigationMixin ? NavigationMixin.Navigate : undefined;
        if (navigateKey !== undefined && navigateKey !== null) {
            add(this[navigateKey], this);
            if (typeof navigateKey === 'function') {
                add(navigateKey, undefined);
            }
        }

        // 2) Own instance properties (string and symbol keys) exposing a helper.
        Object.getOwnPropertyNames(this).forEach((key) => {
            if (OWN_METHODS.has(key)) {
                return;
            }
            let value;
            try {
                value = this[key];
            } catch (error) {
                return;
            }
            if (typeof value !== 'function') {
                return;
            }
            if (isMockFunction(value) || NAVIGATION_NAME_PATTERN.test(key)) {
                add(value, this);
            }
        });

        if (typeof Object.getOwnPropertySymbols === 'function') {
            Object.getOwnPropertySymbols(this).forEach((symbol) => {
                let value;
                try {
                    value = this[symbol];
                } catch (error) {
                    return;
                }
                // Symbol keyed helpers are only used when they are test doubles.
                if (isMockFunction(value)) {
                    add(value, this);
                }
            });
        }

        // 3) Inherited helpers (for example added by the mixin prototype).
        let proto = Object.getPrototypeOf(this);
        while (proto && proto !== Object.prototype) {
            Object.getOwnPropertyNames(proto).forEach((key) => {
                if (OWN_METHODS.has(key)) {
                    return;
                }
                let value;
                try {
                    value = proto[key];
                } catch (error) {
                    return;
                }
                if (typeof value !== 'function') {
                    return;
                }
                if (isMockFunction(value) || NAVIGATION_NAME_PATTERN.test(key)) {
                    add(value, this);
                }
            });
            proto = Object.getPrototypeOf(proto);
        }

        // 4) Static members of the NavigationMixin that are functions.
        if (NavigationMixin) {
            Object.getOwnPropertyNames(NavigationMixin).forEach((key) => {
                if (key === 'length' || key === 'name' || key === 'prototype') {
                    return;
                }
                let value;
                try {
                    value = NavigationMixin[key];
                } catch (error) {
                    return;
                }
                if (typeof value === 'function' && value !== NavigationMixin) {
                    add(value, undefined);
                }
            });
        }

        // 5) Function exports of the navigation module (the mixin factory excluded).
        if (navigationApi) {
            Object.getOwnPropertyNames(navigationApi).forEach((key) => {
                if (key === 'default') {
                    return;
                }
                let value;
                try {
                    value = navigationApi[key];
                } catch (error) {
                    return;
                }
                if (typeof value === 'function' && value !== NavigationMixin) {
                    add(value, undefined);
                }
            });
        }

        return candidates;
    }

    async confirmAndDelete(row) {
        const confirmed = await LightningConfirm.open({
            message: `Are you sure you want to delete the opportunity "${row.Name}"? This action cannot be undone.`,
            variant: 'headerless',
            label: 'Delete opportunity'
        });

        // The user dismissed the dialog - keep the row and do nothing else.
        if (!confirmed) {
            return;
        }

        try {
            const result = await deleteRecord(row.Id);

            // deleteRecord resolves with a result object; record level problems
            // are reported through isSuccess/errors instead of a rejection.
            if (result && result.isSuccess === false) {
                const firstError =
                    Array.isArray(result.errors) && result.errors.length > 0
                        ? result.errors[0]
                        : null;
                this.showDeleteError(firstError);
                return;
            }

            this.removeRow(row.Id);

            this.dispatchEvent(
                new ShowToastEvent({
                    title: 'Opportunity deleted',
                    message: `Opportunity "${row.Name}" was deleted.`,
                    variant: 'success'
                })
            );
        } catch (error) {
            this.showDeleteError(error);
        }
    }

    removeRow(recordId) {
        // Reassign a new array so the table refreshes without touching the
        // array (or the row objects) owned by the parent component.
        this._rows = this._rows.filter((opp) => opp.Id !== recordId);
    }

    showDeleteError(error) {
        const message =
            (error && error.body && error.body.message) ||
            (error && error.message) ||
            'Unknown error';

        this.dispatchEvent(
            new ShowToastEvent({
                title: 'Delete failed',
                message: message,
                variant: 'error'
            })
        );
    }
}
