/**
 * RecurringGiftService
 *
 * Creates NPSP Enhanced Recurring Donations (npe03__Recurring_Donation__c) for the
 * monthly gift sign-ups that arrive from the donation web form.
 *
 * Design notes
 *  - Every request is validated BEFORE any DML runs. If one (or more) request is invalid
 *    the whole call is rejected with a RecurringGiftException and nothing is written.
 *  - The batch is written with a single DML statement (one insert) and this class runs
 *    no SOQL at all, so a 200 request call stays well inside the "1 SOQL / 1 DML" budget.
 *  - Installment Opportunities are deliberately NOT created here. NPSP's own Enhanced
 *    Recurring Donation processing generates the Opportunities from the recurring
 *    donation record (npe03__Next_Payment_Date__c, npsp__StartDate__c,
 *    npsp__Day_of_Month__c, npsp__Always_Use_Last_Day_Of_Month__c, ...).
 */
public with sharing class RecurringGiftService {

    /* ------------------------------------------------------------------ *
     * Public API
     * ------------------------------------------------------------------ */

    public class RecurringGiftException extends Exception {}

    public class GiftRequest {
        public Id contactId;
        public Decimal amount;
        public Integer dayOfMonth;    // 1-31
        public Date startDate;
        public Integer installments;  // null or 0 = no end date
        public String paymentMethod;  // 'Credit Card', 'ACH' or 'Check'
    }

    /* ------------------------------------------------------------------ *
     * NPSP picklist / field values
     * ------------------------------------------------------------------ */

    // npe03__Schedule_Type__c
    private static final String SCHEDULE_TYPE_OPEN  = 'Open';
    private static final String SCHEDULE_TYPE_FIXED = 'Fixed';

    // npe03__Open_Ended_Status__c
    private static final String OPEN_ENDED_STATUS_ACTIVE = 'Active';

    // npsp__Status__c
    private static final String STATUS_ACTIVE = 'Active';

    // npsp__RecurringType__c
    private static final String RECURRING_TYPE_ENHANCED = 'Enhanced';

    // npsp__InstallmentFrequency__c - this service only creates monthly schedules
    private static final String INSTALLMENT_FREQUENCY_MONTHLY = 'Monthly';

    // npe03__Installment_Period__c - NPSP's numeric value for a monthly installment
    // period (Installment_Period metadata: one installment per month).
    private static final Integer INSTALLMENT_PERIOD_MONTHLY = 12;

    // The web form's "31" means "last day of the month" and is stored with NPSP's own
    // last-day-of-month option rather than as a plain day number.
    private static final Integer LAST_DAY_OF_MONTH_INPUT = 31;

    /* ------------------------------------------------------------------ *
     * Entry point
     * ------------------------------------------------------------------ */

    /**
     * Creates one Enhanced Recurring Donation per request.
     *
     * @param requests  the gift sign-ups collected from the donation form
     * @return          the new recurring donation Ids, in the same order as the requests
     * @throws RecurringGiftException  if any request is invalid or the insert fails
     */
    public static List<Id> createMonthlyGifts(List<GiftRequest> requests) {
        List<Id> createdIds = new List<Id>();

        // A null or empty request list is a no-op.
        if (requests == null || requests.isEmpty()) {
            return createdIds;
        }

        List<String> errors = new List<String>();
        List<npe03__Recurring_Donation__c> donations = new List<npe03__Recurring_Donation__c>();

        // ---------- validate + build (no DML yet) ----------
        for (Integer i = 0; i < requests.size(); i++) {
            GiftRequest request = requests[i];
            String label = 'Gift request ' + i + ': ';

            if (request == null) {
                errors.add(label + 'request is null.');
                continue;
            }

            Boolean isValid = true;

            if (request.contactId == null) {
                errors.add(label + 'contactId is required.');
                isValid = false;
            } else if (!String.valueOf(request.contactId).startsWith('003')) {
                errors.add(label + 'contactId must be the Id of a Contact (the donor).');
                isValid = false;
            }

            if (request.amount == null || request.amount <= 0) {
                errors.add(label + 'amount must be a positive number.');
                isValid = false;
            }

            if (request.dayOfMonth == null || request.dayOfMonth < 1 || request.dayOfMonth > 31) {
                errors.add(label + 'dayOfMonth must be between 1 and 31.');
                isValid = false;
            }

            if (request.startDate == null) {
                errors.add(label + 'startDate is required.');
                isValid = false;
            }

            if (request.installments != null && request.installments < 0) {
                errors.add(label + 'installments must be null, 0 (open ended) or a positive number.');
                isValid = false;
            }

            if (!isValid) {
                continue;
            }

            // 31 on the form means "last day of the month"; 29 and 30 are stored as
            // those literal days.
            Boolean useLastDayOfMonth = (request.dayOfMonth == LAST_DAY_OF_MONTH_INPUT);

            // null or 0 installments => open ended (no end date)
            Boolean isOpenEnded = (request.installments == null || request.installments == 0);

            // First installment: the first day-of-month on or after the start date.
            Date firstPaymentDate = firstPaymentDate(request.startDate, request.dayOfMonth, useLastDayOfMonth);

            npe03__Recurring_Donation__c donation = new npe03__Recurring_Donation__c(
                // Donor
                npe03__Contact__c = request.contactId,

                // Amount of every installment
                npe03__Amount__c = request.amount,

                // Monthly schedule
                npe03__Installment_Period__c = INSTALLMENT_PERIOD_MONTHLY,
                npsp__InstallmentFrequency__c = INSTALLMENT_FREQUENCY_MONTHLY,
                npsp__Day_of_Month__c = request.dayOfMonth,
                npsp__Always_Use_Last_Day_Of_Month__c = useLastDayOfMonth,

                // Open ended vs. fixed length
                npe03__Schedule_Type__c = isOpenEnded ? SCHEDULE_TYPE_OPEN : SCHEDULE_TYPE_FIXED,
                npe03__Installments__c = isOpenEnded ? null : request.installments,
                npe03__Open_Ended_Status__c = isOpenEnded ? OPEN_ENDED_STATUS_ACTIVE : null,

                // Dates
                npe03__Date_Established__c = Date.today(),
                npe03__Next_Payment_Date__c = firstPaymentDate,
                npsp__StartDate__c = request.startDate,

                // Status / type
                npsp__Status__c = STATUS_ACTIVE,
                npsp__RecurringType__c = RECURRING_TYPE_ENHANCED
            );

            if (!isOpenEnded) {
                // Date of the last planned installment.
                donation.npsp__EndDate__c = installmentDate(
                    firstPaymentDate,
                    request.installments - 1,
                    request.dayOfMonth,
                    useLastDayOfMonth
                );
            }

            // Payment method is stored exactly as the form sent it.
            if (request.paymentMethod != null && String.isNotBlank(request.paymentMethod)) {
                donation.npsp__PaymentMethod__c = request.paymentMethod.trim();
            }

            donations.add(donation);
        }

        // ---------- all validation happens before any DML ----------
        if (!errors.isEmpty()) {
            throw new RecurringGiftException(
                'Recurring gifts could not be created. ' + String.join(errors, ' ')
            );
        }

        // ---------- single DML statement ----------
        try {
            insert donations;
        } catch (DmlException e) {
            throw new RecurringGiftException(
                'Recurring gifts could not be created: ' + e.getMessage()
            );
        }

        // insert results keep the order of the records that were sent, so the Ids are
        // returned in request order.
        for (npe03__Recurring_Donation__c donation : donations) {
            createdIds.add(donation.Id);
        }

        return createdIds;
    }

    /* ------------------------------------------------------------------ *
     * Date helpers (no SOQL, no DML)
     * ------------------------------------------------------------------ */

    /**
     * First installment date: the first occurrence of the requested day of month that
     * falls on or after the start date.
     */
    private static Date firstPaymentDate(Date startDate, Integer dayOfMonth, Boolean useLastDayOfMonth) {
        Date candidate = dateInMonth(startDate, 0, dayOfMonth, useLastDayOfMonth);
        if (candidate < startDate) {
            candidate = dateInMonth(startDate, 1, dayOfMonth, useLastDayOfMonth);
        }
        return candidate;
    }

    /**
     * The installment that is monthsToAdd months after the first installment,
     * keeping the requested day of month (or the last day of the month).
     */
    private static Date installmentDate(Date firstPaymentDate, Integer monthsToAdd,
                                        Integer dayOfMonth, Boolean useLastDayOfMonth) {
        return dateInMonth(firstPaymentDate, monthsToAdd, dayOfMonth, useLastDayOfMonth);
    }

    /**
     * Builds the date for the given month offset that matches the schedule:
     *  - when useLastDayOfMonth is true -> the last day of that month
     *  - otherwise the requested day of month, clamped to the last day of that month
     *    (for example day 31 in a 30 day month becomes the 30th)
     */
    private static Date dateInMonth(Date anchor, Integer monthsToAdd, Integer dayOfMonth,
                                    Boolean useLastDayOfMonth) {
        Date firstOfMonth = Date.newInstance(anchor.year(), anchor.month(), 1).addMonths(monthsToAdd);

        if (useLastDayOfMonth) {
            // first day of the following month minus one day = last day of this month
            return firstOfMonth.addMonths(1).toDate() - 1;
        }

        Integer lastDayOfMonth = Date.daysInMonth(firstOfMonth.year(), firstOfMonth.month());
        Integer day = (dayOfMonth > lastDayOfMonth) ? lastDayOfMonth : dayOfMonth;

        return Date.newInstance(firstOfMonth.year(), firstOfMonth.month(), day);
    }
}
