/**
 * @description
 * Replaces the GAU Allocations of an Opportunity with a percentage based split.
 *
 * Design notes
 * ------------
 * - The percentages supplied by the caller are the source of truth. Every allocation is
 *   stored with its npsp__Percent__c value and with the matching npsp__Amount__c value for
 *   the current Opportunity Amount.
 * - npsp__Payment__c is deliberately left empty. NPSP keeps percent based (that is, non
 *   payment) allocations in sync by itself: when the Amount of the Opportunity is corrected
 *   later - for example a $1,000 gift that is corrected to $2,000 - NPSP recalculates the
 *   allocation Amounts from the stored percentages, so the $600 / $400 split becomes
 *   $1,200 / $800 without any additional code from us. Because of that, neither the Amount
 *   nor the Percentage of these allocations may be edited by hand - there would be nothing
 *   left for NPSP to recalculate from.
 * - All validation happens before any data is changed. If a check fails an
 *   AllocationException is thrown and nothing is created, changed or deleted.
 * - Everything is done in a single, bulk safe transaction (one query per object, one
 *   delete and one insert), so the whole call is atomic: a failure rolls back both the
 *   delete of the old allocations and the insert of the new ones.
 */
public with sharing class GauAllocationService {

    /** Thrown when the request is invalid or when the allocations cannot be saved. */
    public class AllocationException extends Exception {}

    /** Number of decimals used for allocation amounts. */
    private static final Integer CURRENCY_SCALE = 2;

    /** The percentages of a single gift may never add up to more than 100%. */
    private static final Decimal MAX_TOTAL_PERCENT = 100;

    /** Fields that have to be writable in order to save a percentage based allocation. */
    private static final List<String> REQUIRED_ALLOCATION_FIELDS = new List<String>{
        'npsp__Opportunity__c',
        'npsp__General_Accounting_Unit__c',
        'npsp__Amount__c',
        'npsp__Percent__c'
    };

    /**
     * @description Replaces all existing GAU allocations of an Opportunity with one allocation
     *              per General Accounting Unit / percentage pair.
     * @param opportunityId   Id of the Opportunity (the gift) the allocations belong to.
     * @param percentByGauId Map of npsp__General_Accounting_Unit__c Id to percentage
     *                       (60 means 60% of the gift).
     * @return The allocations that were created (with their Ids populated).
     * @throws AllocationException If the request is invalid (null or empty map, null or non
     *                             positive percentage, total above 100%, unknown or inactive
     *                             General Accounting Unit) or if the allocations cannot be
     *                             saved.
     */
    public static List<npsp__Allocation__c> allocateByPercent(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        // 1. Validate everything up front - no data is touched until every check passed.
        validateRequest(opportunityId, percentByGauId);
        assertAccess();

        // 2. Load the General Accounting Units and make sure they may be allocated to.
        Map<Id, npsp__General_Accounting_Unit__c> gaus = loadGaus(percentByGauId.keySet());
        assertGausUsable(percentByGauId, gaus);

        // 3. Load the Opportunity (and therefore the amount that has to be split).
        Opportunity opportunity = loadOpportunity(opportunityId);

        // 4. Build the new allocations (percent plus the matching amount).
        List<npsp__Allocation__c> allocations = buildAllocations(opportunity, percentByGauId);

        // 5. Replace the existing allocations and insert the new ones.
        removeExistingAllocations(opportunityId);
        return insertAllocations(allocations);
    }

    // -------------------------------------------------------------------------------------
    // Validation
    // -------------------------------------------------------------------------------------

    /**
     * @description Validates the incoming request. Nothing is written before this passes.
     */
    private static void validateRequest(Id opportunityId, Map<Id, Decimal> percentByGauId) {
        if (opportunityId == null) {
            throw new AllocationException(
                'An Opportunity Id is required in order to allocate a gift to General Accounting Units.'
            );
        }
        if (percentByGauId == null || percentByGauId.isEmpty()) {
            throw new AllocationException(
                'At least one General Accounting Unit and percentage are required in order to allocate a gift.'
            );
        }

        Decimal totalPercent = 0;
        for (Id gauId : percentByGauId.keySet()) {
            if (gauId == null) {
                throw new AllocationException('A General Accounting Unit Id is required for every allocation.');
            }
            Decimal percent = percentByGauId.get(gauId);
            if (percent == null) {
                throw new AllocationException(
                    'No percentage was supplied for General Accounting Unit ' + gauId + '.'
                );
            }
            if (percent <= 0) {
                throw new AllocationException(
                    'The percentage for General Accounting Unit ' + gauId + ' must be greater than zero.'
                );
            }
            totalPercent = totalPercent.add(percent);
        }

        // A total of 100% or less is allowed - whatever is left over simply stays unallocated.
        if (totalPercent > MAX_TOTAL_PERCENT) {
            throw new AllocationException(
                'The General Accounting Unit percentages add up to ' + totalPercent.setScale(CURRENCY_SCALE) +
                '%, which is more than 100%.'
            );
        }
    }

    /**
     * @description Makes sure the running user may read and write everything this service needs.
     */
    private static void assertAccess() {
        if (!Schema.sObjectType.Opportunity.isAccessible()) {
            throw new AllocationException('You do not have access to read Opportunities.');
        }
        if (!Schema.sObjectType.npsp__General_Accounting_Unit__c.isAccessible()) {
            throw new AllocationException('You do not have access to read General Accounting Units.');
        }
        if (!Schema.sObjectType.npsp__Allocation__c.isCreateable()) {
            throw new AllocationException('You do not have access to create General Accounting Unit allocations.');
        }
        if (!Schema.sObjectType.npsp__Allocation__c.isDeletable()) {
            throw new AllocationException('You do not have access to delete General Accounting Unit allocations.');
        }
        for (String fieldName : REQUIRED_ALLOCATION_FIELDS) {
            if (!isFieldCreateable(fieldName)) {
                throw new AllocationException(
                    'You do not have access to set the ' + fieldName +
                    ' field on General Accounting Unit allocations.'
                );
            }
        }
    }

    /**
     * @description Loads the requested General Accounting Units with a single, bulk safe query.
     */
    private static Map<Id, npsp__General_Accounting_Unit__c> loadGaus(Set<Id> gauIds) {
        Map<Id, npsp__General_Accounting_Unit__c> gaus =
            new Map<Id, npsp__General_Accounting_Unit__c>();
        for (npsp__General_Accounting_Unit__c gau : [
            SELECT Id, Name, npsp__Active__c
            FROM npsp__General_Accounting_Unit__c
            WHERE Id IN :gauIds
        ]) {
            gaus.put(gau.Id, gau);
        }
        return gaus;
    }

    /**
     * @description Every General Accounting Unit has to exist and has to be active.
     */
    private static void assertGausUsable(Map<Id, Decimal> percentByGauId,
                                         Map<Id, npsp__General_Accounting_Unit__c> gaus) {
        for (Id gauId : percentByGauId.keySet()) {
            npsp__General_Accounting_Unit__c gau = gaus.get(gauId);
            if (gau == null) {
                throw new AllocationException(
                    'General Accounting Unit ' + gauId + ' was not found.'
                );
            }
            if (gau.npsp__Active__c != true) {
                throw new AllocationException(
                    'General Accounting Unit ' + gau.Name +
                    ' is not active and cannot be used for a General Accounting Unit allocation.'
                );
            }
        }
    }

    /**
     * @description Loads the Opportunity the allocations belong to.
     */
    private static Opportunity loadOpportunity(Id opportunityId) {
        List<Opportunity> opportunities = [
            SELECT Id, Amount, CampaignId
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];
        if (opportunities.isEmpty()) {
            throw new AllocationException('Opportunity ' + opportunityId + ' was not found.');
        }
        return opportunities[0];
    }

    // -------------------------------------------------------------------------------------
    // Building and saving the allocations
    // -------------------------------------------------------------------------------------

    /**
     * @description Creates one allocation per General Accounting Unit.
     *
     * The Percentage is stored in a way that matches the type of the npsp__Percent__c field:
     * for a Percent field the value is stored as a fraction (60% is stored as 0.6), for a
     * Number field it is stored as supplied (60). That way NPSP - and only NPSP - keeps the
     * Amount of the allocation in sync with the Amount of the Opportunity.
     */
    private static List<npsp__Allocation__c> buildAllocations(Opportunity opportunity,
                                                              Map<Id, Decimal> percentByGauId) {
        Decimal opportunityAmount = opportunity.Amount == null ? Decimal.ZERO : opportunity.Amount;
        Boolean percentFieldIsPercentType = isPercentTypeField();
        Boolean campaignIsWritable = isFieldCreateable('npsp__Campaign__c');

        List<npsp__Allocation__c> allocations = new List<npsp__Allocation__c>();
        for (Id gauId : percentByGauId.keySet()) {
            Decimal percent = percentByGauId.get(gauId);
            npsp__Allocation__c allocation = new npsp__Allocation__c(
                npsp__Opportunity__c = opportunity.Id,
                npsp__General_Accounting_Unit__c = gauId,
                npsp__Amount__c = roundCurrency(opportunityAmount.multiply(percent).divide(100)),
                npsp__Percent__c = percentFieldIsPercentType ? percent.divide(100) : percent
            );
            // npsp__Payment__c and npsp__Recurring_Donation__c are intentionally left empty:
            // payment linked allocations are not recalculated by NPSP and this gift is not
            // a recurring donation.
            // The campaign is inherited from the Opportunity so the allocation rolls up.
            if (campaignIsWritable && opportunity.CampaignId != null) {
                allocation.npsp__Campaign__c = opportunity.CampaignId;
            }
            allocations.add(allocation);
        }
        return allocations;
    }

    /**
     * @description Removes the allocations that currently exist for the Opportunity.
     */
    private static void removeExistingAllocations(Id opportunityId) {
        List<npsp__Allocation__c> existingAllocations = [
            SELECT Id
            FROM npsp__Allocation__c
            WHERE npsp__Opportunity__c = :opportunityId
        ];
        if (existingAllocations.isEmpty()) {
            return;
        }
        try {
            delete existingAllocations;
        } catch (DmlException e) {
            throw new AllocationException(
                'Unable to remove the existing General Accounting Unit allocations for Opportunity ' +
                opportunityId + ': ' + e.getDmlMessage(0)
            );
        } catch (System.NoAccessException e) {
            throw new AllocationException(
                'Insufficient access to delete the existing General Accounting Unit allocations: ' + e.getMessage()
            );
        }
    }

    /**
     * @description Inserts the new allocations and returns them with their Ids.
     */
    private static List<npsp__Allocation__c> insertAllocations(List<npsp__Allocation__c> allocations) {
        try {
            insert allocations;
        } catch (DmlException e) {
            throw new AllocationException(
                'Unable to save the General Accounting Unit allocations: ' + e.getDmlMessage(0)
            );
        } catch (System.NoAccessException e) {
            throw new AllocationException(
                'Insufficient access to save the General Accounting Unit allocations: ' + e.getMessage()
            );
        }
        return allocations;
    }

    // -------------------------------------------------------------------------------------
    // Helpers
    // -------------------------------------------------------------------------------------

    /** Rounds a currency value to two decimals, half up. */
    private static Decimal roundCurrency(Decimal value) {
        return value.setScale(CURRENCY_SCALE, System.Math.RoundingMode.HALF_UP);
    }

    /**
     * @description True when npsp__Percent__c is a Percent field (values are stored as a
     *              fraction, e.g. 60% is stored as 0.6).
     */
    private static Boolean isPercentTypeField() {
        Schema.DescribeFieldResult percentField =
            Schema.SObjectType.npsp__Allocation__c.fields.npsp__Percent__c;
        return percentField != null && percentField.getType() == Schema.DisplayType.PERCENT;
    }

    /**
     * @description True when the running user may create the given field on an allocation.
     */
    private static Boolean isFieldCreateable(String fieldName) {
        Map<String, Schema.SObjectField> allocationFields =
            Schema.SObjectType.npsp__Allocation__c.fields.getMap();
        if (!allocationFields.containsKey(fieldName)) {
            return false;
        }
        return allocationFields.get(fieldName).getDescribe().isCreateable();
    }
