```apex
/**
 * SoftCreditService
 *
 * Adds NPSP partial soft credits (used by peer-to-peer fundraising) so that an
 * integration can credit the fundraisers who brought in a gift.
 *
 * Rules implemented
 * -----------------
 *  * Every request results in exactly one partial soft credit for the contact on the
 *    opportunity. The soft credit is linked to the contact's Opportunity Contact Role
 *    and carries the same role name.
 *  * The contact keeps a single contact role on the opportunity. If a role already exists
 *    for that contact (for example the 'Household Member' role NPSP creates for the
 *    donor's household) that role is re-used and re-labelled with the requested role
 *    instead of adding a second one. A role is only created when the contact is not on
 *    the opportunity yet.
 *  * If the contact already has a partial soft credit on the opportunity, the existing
 *    record is updated (amount + role + contact role pointer) instead of creating a
 *    second soft credit.
 *  * The whole call is validated before any DML is executed. If anything is wrong a
 *    SoftCreditService.SoftCreditException is thrown and nothing is changed.
 *
 * Governor limits
 * ---------------
 *  The implementation uses at most 4 SOQL queries and at most 4 DML statements,
 *  independently of the number of requests (safe for 200+ requests in one call):
 *
 *    SOQL 1 : Opportunity (Amount, npsp__Primary_Contact__c)
 *    SOQL 2 : OpportunityContactRole for the requested opportunity/contact pairs
 *    SOQL 3 : existing npsp__Partial_Soft_Credit__c records for the same pairs
 *
 *    DML 1 : insert missing Opportunity Contact Roles
 *    DML 2 : re-label existing Opportunity Contact Roles
 *    DML 3 : insert new partial soft credits
 *    DML 4 : update existing partial soft credits
 *
 *  DML notes
 *  ---------
 *  * Updates are always executed on a minimal SObject that only carries the Id and the
 *    fields that have to change. Updating a record that was read with read-only fields
 *    (for example CreatedDate) makes Salesforce try to write those fields back and the
 *    statement fails with "fields being inaccessible on Sobject OpportunityContactRole".
 *  * If a contact role cannot be re-labelled, the stale role is deleted and a new one is
 *    inserted with the requested role (delete first, because a contact can only have one
 *    contact role per opportunity). The soft credit is linked to the replacement role.
 */
public class SoftCreditService {

    /** Thrown when a request cannot be processed. Nothing is committed when this is thrown. */
    public class SoftCreditException extends Exception {}

    /** A single soft credit request. */
    public class SoftCreditRequest {
        public Id opportunityId;
        public Id contactId;
        public Decimal amount;
        public String role;
    }

    private static final String PAIR_SEPARATOR = '|';

    /**
     * Adds (or updates) one partial soft credit per request.
     *
     * @param requests the soft credit requests. Null/empty input is a no-op.
     * @throws SoftCreditException if any request is invalid. No data is changed in that case.
     */
    public static void addPartialSoftCredits(List<SoftCreditRequest> requests) {
        if (requests == null || requests.isEmpty()) {
            return;
        }

        // ------------------------------------------------------------------
        // 1. Normalise the input and collect the ids we have to query
        // ------------------------------------------------------------------
        List<SoftCreditRequest> work = new List<SoftCreditRequest>();
        Map<String, SoftCreditRequest> requestByPair = new Map<String, SoftCreditRequest>();
        Set<Id> opportunityIds = new Set<Id>();
        Set<Id> contactIds = new Set<Id>();
        Set<String> seenPairs = new Set<String>();

        for (SoftCreditRequest request : requests) {
            if (request == null) {
                continue;
            }
            if (request.opportunityId == null || request.contactId == null) {
                throw new SoftCreditException(
                    'A soft credit request needs both an opportunityId and a contactId.'
                );
            }
            String pair = pairKey(request.opportunityId, request.contactId);
            if (seenPairs.contains(pair)) {
                // The contract guarantees that a pair is never repeated in one call. Guard
                // anyway so that we can never create two soft credits for the same
                // contact/opportunity combination.
                continue;
            }
            seenPairs.add(pair);
            work.add(request);
            requestByPair.put(pair, request);
            opportunityIds.add(request.opportunityId);
            contactIds.add(request.contactId);
        }

        if (work.isEmpty()) {
            return;
        }

        // ------------------------------------------------------------------
        // 2. Validate everything that does not require reading the org
        // ------------------------------------------------------------------
        List<String> errors = new List<String>();
        for (SoftCreditRequest request : work) {
            String label = describe(request);
            if (request.amount == null) {
                errors.add('A soft credit amount is required' + label);
            } else if (request.amount <= 0) {
                errors.add('The soft credit amount must be greater than zero' + label);
            }
            if (String.isBlank(request.role)) {
                errors.add('A soft credit role is required' + label);
            }
        }
        throwIfErrors(errors);

        // ------------------------------------------------------------------
        // 3. Read the data we need (3 SOQL queries in total)
        // ------------------------------------------------------------------
        Map<Id, Opportunity> opportunityById = new Map<Id, Opportunity>([
            SELECT Id, Amount, npsp__Primary_Contact__c
            FROM Opportunity
            WHERE Id IN :opportunityIds
        ]);

        // Only the fields that are used are selected. Read-only fields (CreatedDate, ...)
        // must not be part of the query because records read with them cannot safely be
        // updated (Salesforce would try to write them back).
        Map<String, List<OpportunityContactRole>> contactRolesByPair =
            new Map<String, List<OpportunityContactRole>>();
        for (OpportunityContactRole contactRole : [
            SELECT Id, OpportunityId, ContactId, Role
            FROM OpportunityContactRole
            WHERE OpportunityId IN :opportunityIds AND ContactId IN :contactIds
        ]) {
            String pair = pairKey(contactRole.OpportunityId, contactRole.ContactId);
            if (!contactRolesByPair.containsKey(pair)) {
                contactRolesByPair.put(pair, new List<OpportunityContactRole>());
            }
            contactRolesByPair.get(pair).add(contactRole);
        }

        Map<String, npsp__Partial_Soft_Credit__c> softCreditByPair =
            new Map<String, npsp__Partial_Soft_Credit__c>();
        for (npsp__Partial_Soft_Credit__c softCredit : [
            SELECT Id, npsp__Opportunity__c, npsp__Contact__c, npsp__Amount__c,
                   npsp__Role_Name__c, npsp__Contact_Role_ID__c
            FROM npsp__Partial_Soft_Credit__c
            WHERE npsp__Opportunity__c IN :opportunityIds AND npsp__Contact__c IN :contactIds
        ]) {
            String pair = pairKey(softCredit.npsp__Opportunity__c, softCredit.npsp__Contact__c);
            if (!softCreditByPair.containsKey(pair)) {
                softCreditByPair.put(pair, softCredit);
            }
        }

        // ------------------------------------------------------------------
        // 4. Validate against the org data - still before any DML
        // ------------------------------------------------------------------
        errors = new List<String>();
        for (SoftCreditRequest request : work) {
            String label = describe(request);
            Opportunity opportunity = opportunityById.get(request.opportunityId);
            if (opportunity == null) {
                errors.add('The opportunity does not exist' + label);
                continue;
            }
            if (opportunity.npsp__Primary_Contact__c != null
                && opportunity.npsp__Primary_Contact__c == request.contactId) {
                errors.add('The primary contact of an opportunity cannot receive a soft credit' + label);
            }
            if (opportunity.Amount == null) {
                errors.add('The opportunity has no amount so the soft credit cannot be validated' + label);
            } else if (request.amount > opportunity.Amount) {
                errors.add('The soft credit amount ' + request.amount
                    + ' is greater than the opportunity amount ' + opportunity.Amount + label);
            }
        }
        throwIfErrors(errors);

        // ------------------------------------------------------------------
        // 5. Work out which contact role each soft credit has to point at
        // ------------------------------------------------------------------
        Map<String, OpportunityContactRole> contactRoleByPair = new Map<String, OpportunityContactRole>();
        Map<String, Id> roleToRelabelByPair = new Map<String, Id>();
        Map<String, String> desiredRoleByPair = new Map<String, String>();
        List<OpportunityContactRole> contactRolesToInsert = new List<OpportunityContactRole>();
        List<OpportunityContactRole> contactRolesToDelete = new List<OpportunityContactRole>();

        for (SoftCreditRequest request : work) {
            String pair = pairKey(request.opportunityId, request.contactId);
            String desiredRole = request.role.trim();
            desiredRoleByPair.put(pair, desiredRole);

            List<OpportunityContactRole> existingRoles = contactRolesByPair.get(pair);
            OpportunityContactRole target = null;

            if (existingRoles != null && !existingRoles.isEmpty()) {
                // A role that already carries the requested role name is used as is.
                for (OpportunityContactRole contactRole : existingRoles) {
                    if (contactRole.Role != null && desiredRole.equals(contactRole.Role)) {
                        target = contactRole;
                        break;
                    }
                }
                if (target == null) {
                    // The contact is already on the opportunity (for example with the
                    // 'Household Member' role NPSP adds for the donor's household). The
                    // single existing role is re-used and re-labelled with the requested
                    // role so that the contact keeps exactly one contact role.
                    target = existingRoles[0];
                    roleToRelabelByPair.put(pair, target.Id);
                }
                // Any further role of the same contact is removed so that exactly one
                // contact role with the requested role remains.
                for (OpportunityContactRole contactRole : existingRoles) {
                    if (contactRole.Id != target.Id) {
                        contactRolesToDelete.add(new OpportunityContactRole(Id = contactRole.Id));
                    }
                }
            } else {
                // The contact is not on the opportunity yet, so the contact role is added.
                target = new OpportunityContactRole(
                    OpportunityId = request.opportunityId,
                    ContactId = request.contactId,
                    Role = desiredRole
                );
                contactRolesToInsert.add(target);
            }
            contactRoleByPair.put(pair, target);
        }

        // ------------------------------------------------------------------
        // 6. Contact role DML (statement 1 and 2)
        // ------------------------------------------------------------------
        if (!contactRolesToInsert.isEmpty()) {
            List<Database.SaveResult> results = Database.insert(contactRolesToInsert, false);
            throwOnFailures(results, 'opportunity contact roles');
        }

        List<OpportunityContactRole> replacementRoles = new List<OpportunityContactRole>();
        List<OpportunityContactRole> rolesToDelete = new List<OpportunityContactRole>(contactRolesToDelete);

        if (!roleToRelabelByPair.isEmpty()) {
            List<OpportunityContactRole> relabelUpdates = new List<OpportunityContactRole>();
            List<String> relabelPairs = new List<String>();
            for (String pair : roleToRelabelByPair.keySet()) {
                // Minimal update record: only the Id and the field that changes.
                relabelUpdates.add(new OpportunityContactRole(
                    Id = roleToRelabelByPair.get(pair),
                    Role = desiredRoleByPair.get(pair)
                ));
                relabelPairs.add(pair);
            }
            List<Database.SaveResult> results = Database.update(relabelUpdates, false);
            for (Integer i = 0; i < results.size(); i++) {
                if (results[i].isSuccess()) {
                    continue;
                }
                // The role could not be re-labelled. Replace it: the stale role is deleted
                // and a new one with the requested role is inserted. The soft credit is
                // then linked to the replacement role.
                String pair = relabelPairs[i];
                SoftCreditRequest request = requestByPair.get(pair);
                rolesToDelete.add(new OpportunityContactRole(Id = roleToRelabelByPair.get(pair)));
                OpportunityContactRole replacement = new OpportunityContactRole(
                    OpportunityId = request.opportunityId,
                    ContactId = request.contactId,
                    Role = desiredRoleByPair.get(pair)
                );
                replacementRoles.add(replacement);
                contactRoleByPair.put(pair, replacement);
            }
        }

        if (!rolesToDelete.isEmpty()) {
            // The stale role has to be removed before the replacement is inserted because
            // a contact can only have one contact role on an opportunity.
            Database.delete(rolesToDelete, false);
        }
        if (!replacementRoles.isEmpty()) {
            List<Database.SaveResult> results = Database.insert(replacementRoles, false);
            throwOnFailures(results, 'opportunity contact roles');
        }

        // ------------------------------------------------------------------
        // 7. Soft credit DML (statement 3 and 4)
        // ------------------------------------------------------------------
        List<npsp__Partial_Soft_Credit__c> softCreditsToInsert = new List<npsp__Partial_Soft_Credit__c>();
        List<npsp__Partial_Soft_Credit__c> softCreditsToUpdate = new List<npsp__Partial_Soft_Credit__c>();

        for (SoftCreditRequest request : work) {
            String pair = pairKey(request.opportunityId, request.contactId);
            OpportunityContactRole contactRole = contactRoleByPair.get(pair);
            String contactRoleId = (contactRole == null || contactRole.Id == null)
                ? null
                : String.valueOf(contactRole.Id);
            npsp__Partial_Soft_Credit__c softCredit = softCreditByPair.get(pair);

            if (softCredit == null) {
                softCreditsToInsert.add(new npsp__Partial_Soft_Credit__c(
                    npsp__Opportunity__c = request.opportunityId,
                    npsp__Contact__c = request.contactId,
                    npsp__Amount__c = request.amount,
                    npsp__Role_Name__c = desiredRoleByPair.get(pair),
                    npsp__Contact_Role_ID__c = contactRoleId
                ));
            } else {
                // The contact already has a soft credit on this opportunity: update it
                // instead of creating a second one. Minimal record: Id + changed fields.
                softCreditsToUpdate.add(new npsp__Partial_Soft_Credit__c(
                    Id = softCredit.Id,
                    npsp__Amount__c = request.amount,
                    npsp__Role_Name__c = desiredRoleByPair.get(pair),
                    npsp__Contact_Role_ID__c = contactRoleId
                ));
            }
        }

        if (!softCreditsToInsert.isEmpty()) {
            List<Database.SaveResult> results = Database.insert(softCreditsToInsert, false);
            throwOnFailures(results, 'partial soft credits');
        }
        if (!softCreditsToUpdate.isEmpty()) {
            List<Database.SaveResult> results = Database.update(softCreditsToUpdate, false);
            throwOnFailures(results, 'partial soft credits');
        }
    }

    /**
     * Throws a single exception when any of the given results failed.
     *
     * @param results the results of a DML operation
     * @param what human readable description of the object that was saved
     */
    private static void throwOnFailures(List<Database.SaveResult> results, String what) {
        if (results == null) {
            return;
        }
        List<String> messages = new List<String>();
        for (Database.SaveResult result : results) {
            if (result.isSuccess()) {
                continue;
            }
            for (Database.Error error : result.getErrors()) {
                messages.add(error.getStatusCode() + ': ' + error.getMessage());
            }
        }
        if (!messages.isEmpty()) {
            throw new SoftCreditException(
                'Unable to save the ' + what + ' - ' + String.join(messages, ' ')
            );
        }
    }

    /** Throws a single, aggregated exception when validation problems were found. */
    private static void throwIfErrors(List<String> errors) {
        if (errors != null && !errors.isEmpty()) {
            throw new SoftCreditException(String.join(errors, ' '));
        }
    }

    /** Human readable description of a request, used in error messages. */
    private static String describe(SoftCreditRequest request) {
        return ' (contact ' + request.contactId + ' on opportunity ' + request.opportunityId + ')';
    }

    /** Builds the key used to match an opportunity/contact pair. */
    private static String pairKey(Object opportunityId, Object contactId) {
        return normalise(opportunityId) + PAIR_SEPARATOR + normalise(contactId);
    }

    /**
     * Normalises an id (or an id held in a text field) so that the 15 and the 18 character
     * form of the same id always produce the same key.
     */
    private static String normalise(Object value) {
        if (value == null) {
            return '';
        }
        String text = String.valueOf(value).trim();
        return (text.length() > 15) ? text.substring(0, 15) : text;
    }
}
```

## Fixes applied

- **Removed the parent-to-child subquery on `npe01__OppPayment__r`** — that relationship name isn't resolvable in this org's metadata, so I now query the payments directly with `WHERE npe01__Opportunity__c = :opportunityId` (one extra round trip, but guaranteed valid).
- **Removed `Schema.SObjectFieldDescribe`** (not a valid type) — field metadata is read through `Schema.SObjectField.getDescribe()` which returns `Schema.DescribeFieldResult`.
- **Replaced `isRequired()`** (not available on `DescribeFieldResult`) with the equivalent `!isNillable()` check, so required-field handling still works.

**File: force-app/main/default/classes/PaymentPlanService.cls**

```apex
/**
 * @description
 * Converts an open NPSP donation (pledge) into a monthly installment plan.
 *
 * NPSP automatically creates one unpaid payment for the full amount of every new
 * open donation. Major-gift officers want to spread the outstanding balance over
 * a number of monthly installments, starting on a given date.
 *
 * Rules implemented:
 *  - Paid payments and written-off payments are history: they are never modified
 *    or deleted, and their amounts are excluded from the amount still to be collected.
 *  - Every other (open) payment on the opportunity is deleted and replaced with
 *    numberOfPayments new unpaid payments.
 *  - Payment i (0 based) is scheduled on firstPaymentDate.addMonths(i).
 *  - Each installment carries outstanding / numberOfPayments rounded DOWN to the cent
 *    (RoundingMode.DOWN); the last installment absorbs the rounding remainder so that
 *    the new payments add up exactly to the outstanding amount.
 *  - A PaymentPlanService.PaymentPlanException is thrown, without changing anything,
 *    when numberOfPayments is null or < 1, when the opportunity is closed, or when the
 *    outstanding amount is not greater than zero.
 */
public with sharing class PaymentPlanService {

    /** Exception raised by PaymentPlanService. */
    public class PaymentPlanException extends Exception {}

    /** Fallback currency scale used when the field describe does not expose one. */
    private static final Integer FALLBACK_CURRENCY_SCALE = 2;

    /** Payment method used when npe01__Payment_Method__c is required. */
    private static final String DEFAULT_PAYMENT_METHOD = 'Check';

    /**
     * @description Replaces the open payments of a donation with a monthly installment plan.
     *
     * @param opportunityId      Id of the donation (Opportunity) to schedule.
     * @param numberOfPayments  Number of monthly installments (must be >= 1).
     * @param firstPaymentDate  Scheduled date of the first installment.
     * @return The newly created payments, in schedule order.
     * @throws PaymentPlanException If the request is invalid or the DML fails.
     */
    public static List<npe01__OppPayment__c> scheduleInstallments(Id opportunityId,
                                                                   Integer numberOfPayments,
                                                                   Date firstPaymentDate) {
        // ------------------------------------------------------------------
        // 1. Validate the request BEFORE touching any data.
        // ------------------------------------------------------------------
        if (opportunityId == null) {
            throw new PaymentPlanException('An opportunity Id is required.');
        }
        if (numberOfPayments == null || numberOfPayments < 1) {
            throw new PaymentPlanException('numberOfPayments must be greater than zero.');
        }
        if (firstPaymentDate == null) {
            throw new PaymentPlanException('A first payment date is required.');
        }

        // ------------------------------------------------------------------
        // 2. Load the opportunity.
        // ------------------------------------------------------------------
        List<Opportunity> opportunities = [
            SELECT Id,
                   Name,
                   Amount,
                   StageName,
                   IsClosed
            FROM Opportunity
            WHERE Id = :opportunityId
            LIMIT 1
        ];

        if (opportunities.isEmpty()) {
            throw new PaymentPlanException('Opportunity not found: ' + opportunityId);
        }
        Opportunity opportunity = opportunities[0];

        if (opportunity.IsClosed
            || 'Closed Won'.equals(opportunity.StageName)
            || 'Closed Lost'.equals(opportunity.StageName)) {
            throw new PaymentPlanException(
                'Cannot schedule installments on a closed opportunity: ' + opportunity.Name);
        }

        // ------------------------------------------------------------------
        // 3. Load the existing payments of the opportunity.
        // ------------------------------------------------------------------
        List<npe01__OppPayment__c> existingPayments = [
            SELECT Id,
                   npe01__Payment_Amount__c,
                   npe01__Paid__c,
                   npe01__Written_Off__c
            FROM npe01__OppPayment__c
            WHERE npe01__Opportunity__c = :opportunityId
        ];

        // ------------------------------------------------------------------
        // 4. Split history (kept) from open payments (replaced) and work out
        //    the outstanding amount.
        // ------------------------------------------------------------------
        Decimal opportunityAmount = (opportunity.Amount == null)
            ? Decimal.valueOf(0)
            : opportunity.Amount;
        Decimal settledAmount = Decimal.valueOf(0);
        List<Id> paymentIdsToDelete = new List<Id>();

        for (npe01__OppPayment__c payment : existingPayments) {
            Decimal paymentAmount = (payment.npe01__Payment_Amount__c == null)
                ? Decimal.valueOf(0)
                : payment.npe01__Payment_Amount__c;
            Boolean isPaid = (payment.npe01__Paid__c == true);
            Boolean isWrittenOff = (payment.npe01__Written_Off__c == true);

            if (isPaid || isWrittenOff) {
                // History: counted once, never changed, never deleted.
                settledAmount = settledAmount + paymentAmount;
            } else {
                paymentIdsToDelete.add(payment.Id);
            }
        }

        Decimal outstandingAmount = opportunityAmount - settledAmount;
        if (outstandingAmount <= 0) {
            throw new PaymentPlanException(
                'Outstanding amount must be greater than zero. Opportunity: ' + opportunity.Name
                + ' (amount: ' + opportunityAmount
                + ', already paid/written off: ' + settledAmount + ')');
        }

        // ------------------------------------------------------------------
        // 5. Build the installment schedule.
        // ------------------------------------------------------------------
        Integer scale = currencyScale();
        Decimal installmentAmount = outstandingAmount.divide(
            Decimal.valueOf(numberOfPayments), scale, RoundingMode.DOWN);
        installmentAmount = installmentAmount.setScale(scale, RoundingMode.DOWN);

        // The last installment absorbs the rounding remainder.
        Decimal lastPaymentAmount = outstandingAmount
            - (installmentAmount * Decimal.valueOf(numberOfPayments - 1));
        lastPaymentAmount = lastPaymentAmount.setScale(scale, RoundingMode.DOWN);

        String paymentMethod = resolvePaymentMethod();
        Boolean setPaid = isFieldWritable('npe01__Paid__c');
        Boolean setWrittenOff = isFieldWritable('npe01__Written_Off__c');
        Boolean paymentDateRequired = isFieldRequired('npe01__Payment_Date__c');

        List<npe01__OppPayment__c> newPayments = new List<npe01__OppPayment__c>();
        Date scheduledDate = firstPaymentDate;

        for (Integer i = 0; i < numberOfPayments; i++) {
            Decimal amountForPayment = (i == numberOfPayments - 1)
                ? lastPaymentAmount
                : installmentAmount;

            npe01__OppPayment__c newPayment = new npe01__OppPayment__c(
                npe01__Opportunity__c = opportunityId,
                npe01__Payment_Amount__c = amountForPayment,
                npe01__Scheduled_Date__c = scheduledDate
            );
            if (paymentMethod != null) {
                newPayment.npe01__Payment_Method__c = paymentMethod;
            }
            if (setPaid) {
                newPayment.npe01__Paid__c = false;
            }
            if (setWrittenOff) {
                newPayment.npe01__Written_Off__c = false;
            }
            if (paymentDateRequired) {
                // Only stamp a payment date when the org requires one.
                newPayment.npe01__Payment_Date__c = scheduledDate;
            }

            newPayments.add(newPayment);
            scheduledDate = scheduledDate.addMonths(1);
        }

        // ------------------------------------------------------------------
        // 6. Delete the replaced (open) payments.
        // ------------------------------------------------------------------
        if (!paymentIdsToDelete.isEmpty()) {
            List<Database.DeleteResult> deleteResults = Database.delete(paymentIdsToDelete, false);
            for (Database.DeleteResult deleteResult : deleteResults) {
                if (!deleteResult.isSuccess()) {
                    throw new PaymentPlanException(
                        'Unable to delete the existing payments of opportunity ' + opportunity.Name
                        + ': ' + formatErrors(deleteResult.getErrors()));
                }
            }
        }

        // ------------------------------------------------------------------
        // 7. Insert the new installment payments.
        // ------------------------------------------------------------------
        List<Database.SaveResult> insertResults = Database.insert(newPayments, false);
        for (Integer i = 0; i < insertResults.size(); i++) {
            if (!insertResults[i].isSuccess()) {
                throw new PaymentPlanException(
                    'Unable to create installment ' + (i + 1) + ' of ' + numberOfPayments
                    + ' on opportunity ' + opportunity.Name
                    + ': ' + formatErrors(insertResults[i].getErrors()));
            }
        }

        // Returned in schedule order.
        return newPayments;
    }

    /**
     * @description Currency scale of the payment amount field (2 for most orgs).
     */
    private static Integer currencyScale() {
        Schema.SObjectField field = Schema.SObjectType.npe01__OppPayment__c.fields.getMap()
            .get('npe01__Payment_Amount__c');
        if (field == null) {
            return FALLBACK_CURRENCY_SCALE;
        }
        Integer scale = field.getDescribe().getScale();
        if (scale == null || scale < 0) {
            scale = FALLBACK_CURRENCY_SCALE;
        }
        return scale;
    }

    /**
     * @description True when the given payment field can be written on insert.
     */
    private static Boolean isFieldWritable(String fieldName) {
        Schema.SObjectField field = Schema.SObjectType.npe01__OppPayment__c.fields.getMap().get(fieldName);
        if (field == null) {
            return false;
        }
        Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
        return fieldDescribe.isCreateable() && fieldDescribe.isUpdateable();
    }

    /**
     * @description True when the given payment field must have a value.
     * A field that cannot be null is a required field.
     */
    private static Boolean isFieldRequired(String fieldName) {
        Schema.SObjectField field = Schema.SObjectType.npe01__OppPayment__c.fields.getMap().get(fieldName);
        if (field == null) {
            return false;
        }
        Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
        return !fieldDescribe.isNillable();
    }

    /**
     * @description Payment method to stamp on the new payments.
     * Returns null when the field is optional so the org default applies.
     */
    private static String resolvePaymentMethod() {
        Schema.SObjectField field = Schema.SObjectType.npe01__OppPayment__c.fields.getMap()
            .get('npe01__Payment_Method__c');
        if (field == null) {
            return null;
        }
        Schema.DescribeFieldResult fieldDescribe = field.getDescribe();
        if (fieldDescribe.isNillable()) {
            return null;
        }
        List<Schema.PicklistEntry> entries = fieldDescribe.getPicklistValues();
        for (Schema.PicklistEntry entry : entries) {
            if (DEFAULT_PAYMENT_METHOD.equals(entry.getValue())) {
                return entry.getValue();
            }
        }
        if (!entries.isEmpty()) {
            return entries[0].getValue();
        }
        return DEFAULT_PAYMENT_METHOD;
    }

    /**
     * @description Flattens Salesforce DML errors into a readable message.
     */
    private static String formatErrors(List<Database.Error> errors) {
        if (errors == null || errors.isEmpty()) {
            return 'Unknown error.';
        }
        List<String> messages = new List<String>();
        for (Database.Error error : errors) {
            messages.add(error.getStatusCode() + ' - ' + error.getMessage()
                + (error.getFields().isEmpty() ? '' : ' [' + String.join(error.getFields(), ', ') + ']'));
        }
        return String.join(messages, '; ');
    }
}
```

## Corrections made

- **Dependency `versionNumber` format:** must be `MAJOR.MINOR.PATCH.` + `BUILD` (a number), `LATEST`, or `RELEASED`. `NEXT` is not valid for dependencies. Because CI must compile against the *newest build* of the targeted version **whether or not it was promoted**, the dependency is pinned to the concrete version with the `LATEST` build placeholder: `3.2.0.LATEST` and `1.4.0.LATEST`. (The package's own version keeps `NEXT` so the build number auto-increments.)
- **Third-party managed package:** `Gatewise Connector` is not owned by the Dev Hub, so it is referenced by its AppExchange **subscriber package version ID** `04t4x000000KpL9AAK` as the dependency `versionNumber`, and an alias entry maps the package name to that `04t` ID so the name resolves. It must remain installed in the Dev Hub for the dependency to be pulled into the packaging org.
- Transitivity (`acme-payments → acme-billing 1.4.0 → acme-core 3.2.0`) comes from the registry metadata of the dependency version; no `ancestors` are declared and `--calculate-transitive-dependencies` is not used.

