```apex
/**
 * @description
 * TAF Trigger Action that collects the Ids of the Opportunities which have to be pushed to the ERP.
 *
 * Rules implemented by this action:
 *  - After insert: every inserted Opportunity has to be synced with the ERP.
 *  - After update: only the Opportunities whose StageName actually changed have to be synced.
 *
 * No job is enqueued from here: the trigger can recurse (a single insert of 250 Opportunities is
 * executed by Salesforce in two chunks, 200 + 50), so enqueueing here would produce more than one
 * job per DML operation. The Ids are buffered in a transaction scoped buffer instead, and the DML
 * finalizer (OpportunityErpSyncFinalizer) drains that buffer and enqueues exactly ONE
 * OpportunityErpSyncJob per DML operation.
 *
 * @see OpportunityErpSyncFinalizer
 * @see OpportunityErpSyncJob
 */
public with sharing class TA_Opportunity_CollectForErpSync implements TriggerAction.AfterInsert, TriggerAction.AfterUpdate {
    /**
     * @description Ids collected since the last DML finalization.
     * Static state is transaction scoped; the buffer is emptied by the finalizer at the end of every
     * DML operation, which guarantees one (and only one) job per DML operation.
     */
    private static final Set<Id> PENDING_OPPORTUNITY_IDS = new Set<Id>();

    /**
     * @description Adds the given Opportunity Ids to the buffer of the current DML operation.
     * @param opportunityIds Ids to be pushed to the ERP by the next DML finalization.
     */
    public static void addPendingOpportunityIds(Set<Id> opportunityIds) {
        if (opportunityIds == null || opportunityIds.isEmpty()) {
            return;
        }
        for (Id opportunityId : opportunityIds) {
            if (opportunityId != null) {
                PENDING_OPPORTUNITY_IDS.add(opportunityId);
            }
        }
    }

    /**
     * @description Returns every buffered Opportunity Id and empties the buffer.
     * Draining (instead of only reading) is what makes the finalizer idempotent within a single
     * DML operation: two separate DML statements in the same transaction therefore produce two
     * jobs, each carrying only its own records.
     * @return Set of Opportunity Ids collected for the DML operation being finalized.
     */
    public static Set<Id> drainPendingOpportunityIds() {
        Set<Id> opportunityIds = new Set<Id>(PENDING_OPPORTUNITY_IDS);
        PENDING_OPPORTUNITY_IDS.clear();
        return opportunityIds;
    }

    /**
     * @description Collects every inserted Opportunity.
     * @param triggerNew The records inserted by the current (possibly recursive) trigger execution.
     */
    public void afterInsert(List<SObject> triggerNew) {
        Set<Id> opportunityIds = new Set<Id>();
        if (triggerNew != null) {
            for (SObject record : triggerNew) {
                if (record instanceof Opportunity && record.Id != null) {
                    opportunityIds.add(record.Id);
                }
            }
        }
        addPendingOpportunityIds(opportunityIds);
    }

    /**
     * @description Collects only the Opportunities whose StageName changed.
     * @param triggerNew The records updated by the current (possibly recursive) trigger execution.
     * @param triggerOld The matching previous versions of those records.
     */
    public void afterUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Set<Id> opportunityIds = new Set<Id>();
        if (triggerNew == null || triggerOld == null) {
            return;
        }
        Integer recordCount = Math.min(triggerNew.size(), triggerOld.size());
        for (Integer i = 0; i < recordCount; i++) {
            SObject newRecord = triggerNew[i];
            SObject oldRecord = triggerOld[i];
            if (!(newRecord instanceof Opportunity) || !(oldRecord instanceof Opportunity)) {
                continue;
            }
            Opportunity opportunityNew = (Opportunity) newRecord;
            Opportunity opportunityOld = (Opportunity) oldRecord;
            if (opportunityNew.StageName != opportunityOld.StageName) {
                opportunityIds.add(opportunityNew.Id);
            }
        }
        addPendingOpportunityIds(opportunityIds);
    }
}
