```apex
/**
 * TA_Contact_PreventDuplicateEmail
 *
 * Trigger Action for the Trigger Actions Framework (TAF 0.3.4) that enforces the
 * following business rule on Contact:
 *
 *   Two contacts that belong to the same account may not share the same email
 *   address (the comparison is case insensitive). Contacts without an account
 *   or without an email address are not checked.
 *
 * Behaviour
 *   - Implements the before insert and the before update context of TAF, so it is
 *     registered twice (once per context) in Trigger_Action__mdt.
 *   - Every violating record receives a record level error (addError); all other
 *     records of the same save are still persisted (partial save works).
 *   - When several records of one save would share the same account + email, the
 *     first record of the list is accepted and every later one is rejected.
 *   - On update only records whose Email or AccountId actually changed are
 *     validated, so pre-existing (legacy) duplicates never block unrelated edits.
 *   - A record never conflicts with itself.
 *   - Bulk safe: at most one SOQL query per trigger execution (200 records).
 */
public class TA_Contact_PreventDuplicateEmail
        implements TriggerAction.BeforeInsert, TriggerAction.BeforeUpdate {

    /** Record level error message used for every violation. */
    public static final String ERROR_MESSAGE = 'Another contact on this account already uses this email address.';

    // -------------------------------------------------------------------------
    // Trigger Action entry points
    // -------------------------------------------------------------------------

    /**
     * Before insert: validate every contact of the save that has an account and
     * an email address.
     */
    public void beforeInsert(List<SObject> triggerNew) {
        List<Contact> candidates = collectCandidates(triggerNew);
        if (candidates.isEmpty()) {
            return;
        }
        // One single query for the whole batch.
        Set<String> existingKeys = queryExistingKeys(candidates, new Set<Id>());
        applyRule(candidates, existingKeys);
    }

    /**
     * Before update: validate only the contacts whose Email or AccountId changed.
     */
    public void beforeUpdate(List<SObject> triggerNew, List<SObject> triggerOld) {
        Map<Id, Contact> oldContactsById = new Map<Id, Contact>();
        for (SObject record : triggerOld) {
            Contact oldContact = (Contact) record;
            oldContactsById.put(oldContact.Id, oldContact);
        }

        List<Contact> candidates = new List<Contact>();
        Set<Id> candidateIds = new Set<Id>();
        for (SObject record : triggerNew) {
            Contact contact = (Contact) record;
            Contact oldContact = oldContactsById.get(contact.Id);
            if (oldContact == null || !isCheckable(contact) || !hasChanged(contact, oldContact)) {
                // Not checkable or nothing relevant changed -> never blocked.
                continue;
            }
            candidates.add(contact);
            candidateIds.add(contact.Id);
        }
        if (candidates.isEmpty()) {
            return;
        }

        // The database rows of the changed records still hold their old values
        // (stale key) and a record must never conflict with itself, so those rows
        // are ignored. Rows of unchanged records of the same save are kept because
        // they still legitimately occupy their account + email combination.
        Set<String> existingKeys = queryExistingKeys(candidates, candidateIds);
        applyRule(candidates, existingKeys);
    }

    // -------------------------------------------------------------------------
    // Helpers
    // -------------------------------------------------------------------------

    /**
     * Returns the contacts of the batch that have to be validated (account and
     * email address present), preserving the order of the trigger list.
     */
    private static List<Contact> collectCandidates(List<SObject> triggerNew) {
        List<Contact> candidates = new List<Contact>();
        for (SObject record : triggerNew) {
            Contact contact = (Contact) record;
            if (isCheckable(contact)) {
                candidates.add(contact);
            }
        }
        return candidates;
    }

    /**
     * Adds the record level error to every candidate whose account + email
     * combination is already taken (by the database or by an earlier record of
     * the same save).
     */
    private static void applyRule(List<Contact> candidates, Set<String> existingKeys) {
        Set<String> seenKeys = new Set<String>();
        for (Contact contact : candidates) {
            String key = buildKey(contact.AccountId, contact.Email);
            if (existingKeys.contains(key) || seenKeys.contains(key)) {
                contact.addError(ERROR_MESSAGE);
            } else {
                // First record of the save wins the combination.
                seenKeys.add(key);
            }
        }
    }

    /** A contact is only checked when it has an account and an email address. */
    private static Boolean isCheckable(Contact contact) {
        return contact != null
                && contact.AccountId != null
                && contact.Email != null
                && String.isNotBlank(contact.Email);
    }

    /** True when the email address or the account of the contact changed. */
    private static Boolean hasChanged(Contact contact, Contact oldContact) {
        if (contact.AccountId != oldContact.AccountId) {
            return true;
        }
        String newEmail = contact.Email == null ? '' : contact.Email;
        String oldEmail = oldContact.Email == null ? '' : oldContact.Email;
        return newEmail != oldEmail;
    }

    /** Case insensitive key of an account + email combination. */
    private static String buildKey(Id accountId, String email) {
        return String.valueOf(accountId) + '|' + email.toLowerCase();
    }

    /**
     * Returns the account + email combinations that already exist in the
     * database. Executes at most one query per trigger execution.
     *
     * @param candidates  the records to check (source of the filter values)
     * @param excludedIds records whose database row must be ignored
     */
    private static Set<String> queryExistingKeys(List<Contact> candidates, Set<Id> excludedIds) {
        Set<String> existingKeys = new Set<String>();
        Set<Id> accountIds = new Set<Id>();
        Set<String> emails = new Set<String>();
        for (Contact contact : candidates) {
            accountIds.add(contact.AccountId);
            emails.add(contact.Email);
        }
        if (accountIds.isEmpty() || emails.isEmpty()) {
            return existingKeys;
        }

        // SOQL compares text values case insensitively, so "Email IN :emails"
        // already matches every casing of the same address.
        List<Contact> existingContacts = [
            SELECT Id, AccountId, Email
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email IN :emails
        ];

        for (Contact existing : existingContacts) {
            if (excludedIds != null && excludedIds.contains(existing.Id)) {
                continue;
            }
            if (existing.AccountId == null || existing.Email == null) {
                continue;
            }
            existingKeys.add(buildKey(existing.AccountId, existing.Email));
        }
        return existingKeys;
    }
}
