/**
 * @description
 * Audit action: creates a Task on an Opportunity whenever its Amount changes (update only).
 *
 * Registered on the Opportunity sObject_Trigger_Setting__mdt record (After_Update__c) with
 * Order__c 10, so it runs BEFORE TA_Opportunity_RoundAmount (Order__c 20).
 *
 * TA_Opportunity_RoundAmount updates the same Opportunities again inside the same transaction,
 * which re-enters this action with a second old/new Amount pair (for example 100.50 -> 101).
 * The audit must therefore be evaluated ONCE per Opportunity per transaction: the rounding is a
 * consequence of the user's change, it is not a separate change.
 *
 * Recursion handling:
 *   evaluatedOpportunityIds is a static Set of the Opportunity Ids already evaluated in an after
 *   update context during this transaction. Apex statics live for the whole transaction, so:
 *     - the first after update pass for a record is evaluated against the real user change, and
 *     - the re-entrant pass caused by the rounding action is skipped entirely.
 *   That also guarantees that an Opportunity whose Amount was not changed by the user does not
 *   produce a task merely because the rounding action adjusted the Amount.
 *
 * Bulk safety:
 *   All tasks for the batch are written with a single DML statement (one insert per trigger
 *   execution), so a 200 record update costs one insert and stays inside the DML row limits.
 */
public with sharing class TA_Opportunity_LogAmountChange implements TriggerAction.AfterUpdate {

    private static final String TASK_SUBJECT = 'Amount changed';
    private static final String TASK_STATUS = 'Completed';

    /**
     * @description Opportunity Ids already evaluated in an after update context during the
     *              current transaction. Static state is reset between transactions, never
     *              inside one.
     */
    private static Set<Id> evaluatedOpportunityIds = new Set<Id>();

    public void afterUpdate(List<Opportunity> triggerNew, List<Opportunity> triggerOld) {
        if (triggerNew == null || triggerNew.isEmpty()) {
            return;
        }

        List<Task> tasks = new List<Task>();
        Integer oldSize = (triggerOld == null) ? 0 : triggerOld.size();

        for (Integer i = 0; i < triggerNew.size(); i++) {
            Opportunity newOpp = triggerNew[i];
            if (newOpp == null || newOpp.Id == null) {
                continue;
            }

            // Recursion guard: only the first after update pass for a record in this transaction
            // is audited. Any later pass is a consequence of an action that already updated the
            // record (the rounding action), so it must not create another Task.
            if (evaluatedOpportunityIds.contains(newOpp.Id)) {
                continue;
            }
            evaluatedOpportunityIds.add(newOpp.Id);

            if (i >= oldSize) {
                continue;
            }
            Opportunity oldOpp = triggerOld[i];
            if (oldOpp == null) {
                continue;
            }

            // Only a genuine Amount change is audited (a blank to a value and a value to a
            // blank count as changes; an unchanged Amount does not).
            if (!amountChanged(oldOpp.Amount, newOpp.Amount)) {
                continue;
            }

            tasks.add(
                new Task(
                    Subject = TASK_SUBJECT,
                    WhatId = newOpp.Id,
                    Status = TASK_STATUS,
                    Description = 'Amount changed from ' + displayAmount(oldOpp.Amount) + ' to ' + displayAmount(newOpp.Amount)
                )
            );
        }

        if (!tasks.isEmpty()) {
            // One bulk insert per trigger execution.
            insert tasks;
        }
    }

    /**
     * @description Compares the old and new Amount values numerically (scale insensitive).
     */
    private static Boolean amountChanged(Decimal oldAmount, Decimal newAmount) {
        if (oldAmount == null && newAmount == null) {
            return false;
        }
        if (oldAmount == null || newAmount == null) {
            return true;
        }
        return oldAmount != newAmount;
    }

    private static String displayAmount(Decimal amount) {
        return (amount == null) ? '(blank)' : '' + amount;
    }
}
```

