/**
 * Contact before-insert trigger action: inherit the parent's billing address.
 *
 * When a new contact has an Account and all four mailing address fields
 * (MailingStreet, MailingCity, MailingPostalCode, MailingCountry) are blank,
 * the Account's billing address is copied onto the contact. A contact that has
 * any mailing field populated keeps its own address. Contacts without an
 * Account are left alone.
 *
 * The parent Account is read from the cache populated by
 * TA_Contact_Queries.Service - this action never queries Accounts itself.
 */
public with sharing class TA_Contact_InheritMailingAddress implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (SObject record : triggerNew) {
            Contact contact = (Contact) record;

            // Contacts without a parent Account are left alone.
            if (contact.AccountId == null) {
                continue;
            }

            // Only inherit when the contact has no mailing address of its own.
            if (String.isNotBlank(contact.MailingStreet)
                || String.isNotBlank(contact.MailingCity)
                || String.isNotBlank(contact.MailingPostalCode)
                || String.isNotBlank(contact.MailingCountry)) {
                continue;
            }

            Account account = accountsById.get(contact.AccountId);
            if (account == null) {
                continue;
            }

            contact.MailingStreet = account.BillingStreet;
            contact.MailingCity = account.BillingCity;
            contact.MailingPostalCode = account.BillingPostalCode;
            contact.MailingCountry = account.BillingCountry;
        }
    }
}
