/**
 * Contact before-insert trigger action: default the Lead Source from the parent.
 *
 * When a new contact has an Account and a blank LeadSource, the Account's
 * AccountSource is copied onto the contact. Contacts without an Account, and
 * contacts that already have a LeadSource, are left alone.
 *
 * The parent Account is read from the cache populated by
 * TA_Contact_Queries.Service - this action never queries Accounts itself.
 */
public with sharing class TA_Contact_DefaultLeadSource implements TriggerAction.BeforeInsert {
    public void beforeInsert(List<SObject> triggerNew) {
        Map<Id, Account> accountsById = TA_Contact_Queries.getInstance().accountsById;

        for (SObject record : triggerNew) {
            Contact contact = (Contact) record;

            // Contacts without a parent Account are left alone.
            if (contact.AccountId == null) {
                continue;
            }

            // Only default the Lead Source when the contact does not have one.
            if (String.isNotBlank(contact.LeadSource)) {
                continue;
            }

            Account account = accountsById.get(contact.AccountId);
            if (account == null || String.isBlank(account.AccountSource)) {
                continue;
            }

            contact.LeadSource = account.AccountSource;
        }
    }
}
